import json

RETRY_STATUSES = {408, 429, 500, 502, 503, 504}


class HarvestError(Exception):
    pass


def _split_outside(text, separator):
    parts, current, in_angle, in_quote = [], [], False, False
    for ch in text:
        if ch == '"' and not in_angle:
            in_quote = not in_quote
        elif ch == "<" and not in_quote:
            in_angle = True
        elif ch == ">" and not in_quote:
            in_angle = False
        if ch == separator and not in_angle and not in_quote:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
    parts.append("".join(current))
    return parts


def _next_link(value):
    for link in _split_outside(value or "", ","):
        link = link.strip()
        if not link.startswith("<") or ">" not in link:
            continue
        url = link[1:link.index(">")]
        for param in _split_outside(link[link.index(">") + 1:], ";"):
            name, eq, raw = param.partition("=")
            if eq and name.strip().lower() == "rel":
                if "next" in raw.strip().strip('"').lower().split():
                    return url
    return None


def _header(headers, name):
    for key, value in headers.items():
        if key.lower() == name:
            return value
    return None


class Harvester:
    def __init__(self, transport, clock, sleep, rng, max_attempts=4, min_interval=0.2):
        self.transport = transport
        self.clock = clock
        self.sleep = sleep
        self.rng = rng
        self.max_attempts = max_attempts
        self.min_interval = min_interval
        self.requests = 0
        self.retries = 0
        self._last_sent = None

    def _send(self, url):
        if self._last_sent is not None:
            wait = self.min_interval - (self.clock() - self._last_sent)
            if wait > 0:
                self.sleep(wait)
        self._last_sent = self.clock()
        self.requests += 1
        return self.transport.send("GET", url, {"Accept": "application/json"})

    def _page(self, url):
        attempt = 0
        while True:
            attempt += 1
            response, error = None, None
            try:
                response = self._send(url)
            except (ConnectionError, TimeoutError) as e:
                error = e
            if error is None and response[0] not in RETRY_STATUSES:
                return response
            if attempt >= self.max_attempts:
                reason = f"status {response[0]}" if error is None else f"{type(error).__name__}: {error}"
                raise HarvestError(f"{url}: gave up after {attempt} attempts ({reason})")
            delay = None
            if response is not None:
                value = _header(response[1], "retry-after")
                if value is not None and str(value).strip().isdigit():
                    delay = int(str(value).strip())
            if delay is None:
                delay = self.rng.uniform(0, min(8, 0.5 * 2 ** (attempt - 1)))
            self.sleep(delay)
            self.retries += 1

    def fetch_all(self, url):
        items, seen_ids, visited = [], set(), set()
        while url is not None:
            if url in visited:
                raise HarvestError(f"pagination loop at {url}")
            visited.add(url)
            status, headers, body = self._page(url)
            if status != 200:
                raise HarvestError(f"{url}: status {status}")
            try:
                data = json.loads(body)
            except (ValueError, TypeError):
                raise HarvestError(f"{url}: the page is not valid JSON")
            if not isinstance(data, dict) or not isinstance(data.get("items"), list):
                raise HarvestError(f"{url}: the page has no items list")
            for item in data["items"]:
                key = item.get("id") if isinstance(item, dict) else None
                if key is not None:
                    if key in seen_ids:
                        continue
                    seen_ids.add(key)
                items.append(item)
            url = _next_link(_header(headers, "link"))
        return items

