import json

class World:
    def __init__(self):
        self.t = 0.0
        self.sleeps = []
        self.sent_at = []
    def clock(self):
        return self.t
    def sleep(self, seconds):
        self.sleeps.append(seconds)
        self.t += seconds

class MaxRng:
    def uniform(self, low, high):
        return high

def page(items, next_url=None, status=200, **headers):
    h = {"Content-Type": "application/json"}
    if next_url:
        h["Link"] = f'<{next_url}>; rel="next"'
    h.update(headers)
    return (status, h, json.dumps({"items": items}).encode())

class Api:
    def __init__(self, world, script):
        self.world = world
        self.script = {url: list(responses) for url, responses in script.items()}
        self.calls = []
    def send(self, method, url, headers):
        assert method == "GET" and headers == {"Accept": "application/json"}
        self.calls.append(url)
        self.world.sent_at.append(self.world.t)
        self.world.t += 0.05
        outcome = self.script[url].pop(0)
        if isinstance(outcome, BaseException):
            raise outcome
        return outcome

def harvest(script, start="https://api/books", **kwargs):
    world = World()
    api = Api(world, script)
    h = Harvester(api, world.clock, world.sleep, MaxRng(), **kwargs)
    return h, api, world, h.fetch_all(start)

@test("three pages, in order")
def _():
    h, api, world, items = harvest({
        "https://api/books": [page([{"id": 1}, {"id": 2}], "https://api/books?page=2")],
        "https://api/books?page=2": [page([{"id": 3}], "https://api/books?page=3")],
        "https://api/books?page=3": [page([{"id": 4}])],
    })
    check_eq(items, [{"id": 1}, {"id": 2}, {"id": 3}, {"id": 4}])
    check_eq(api.calls, ["https://api/books", "https://api/books?page=2", "https://api/books?page=3"])
    check_eq((h.requests, h.retries), (3, 0))

@test("duplicates from shifting pages")
def _():
    h, api, world, items = harvest({
        "https://api/books": [page([{"id": 1}, {"id": 2}], "https://api/books?offset=2")],
        "https://api/books?offset=2": [page([{"id": 2, "dup": True}, {"id": 3}])],
    })
    check_eq(items, [{"id": 1}, {"id": 2}, {"id": 3}])

@test("pacing between requests")
def _():
    h, api, world, items = harvest({
        "https://api/a": [page([{"id": 1}], "https://api/b")],
        "https://api/b": [page([{"id": 2}], "https://api/c")],
        "https://api/c": [page([])],
    }, start="https://api/a", min_interval=0.5)
    gaps = [b - a for a, b in zip(world.sent_at, world.sent_at[1:])]
    check(all(g >= 0.5 - 1e-9 for g in gaps), f"gaps {gaps}")
    check_eq(len(world.sleeps), 2)
    check_near(world.sleeps[0], 0.45)

@test("retries with backoff and Retry-After")
def _():
    h, api, world, items = harvest({
        "https://api/books": [(503, {}, b""), ConnectionError("reset"), (429, {"retry-after": "3"}, b""), page([{"id": 1}], "https://api/books?p=2")],
        "https://api/books?p=2": [TimeoutError("slow"), page([{"id": 2}])],
    })
    check_eq(items, [{"id": 1}, {"id": 2}])
    check_eq((h.requests, h.retries), (6, 4))
    check_eq([s for s in world.sleeps if s > 0.2], [0.5, 1.0, 3, 0.5])

@test("the attempt limit is per page")
def _():
    script = {"https://api/books": [(500, {}, b"")] * 2 + [page([{"id": 1}], "https://api/books?p=2")],
              "https://api/books?p=2": [(502, {}, b"")] * 2 + [page([{"id": 2}])]}
    h, api, world, items = harvest(script, max_attempts=3)
    check_eq(len(items), 2)
    try:
        harvest({"https://api/books": [(503, {}, b"")] * 3}, max_attempts=3)
        check(False, "expected HarvestError")
    except HarvestError:
        pass

@test("failures that stop at once")
def _():
    bad = [
        {"https://api/books": [(404, {}, b"")]},
        {"https://api/books": [(200, {"Content-Type": "application/json"}, b"<html>")]},
        {"https://api/books": [(200, {}, b'{"data": []}')]},
        {"https://api/books": [(200, {}, b"[1, 2]")]},
        {"https://api/books": [page([{"id": 1}], "https://api/books?p=2")], "https://api/books?p=2": [page([{"id": 2}], "https://api/books")]},
    ]
    for script in bad:
        try:
            harvest(script)
            check(False, f"expected HarvestError for {script}")
        except HarvestError:
            pass

